import numpy as np
var=np.var(dv_dt)
base=[np.ones_like(t),x,v,x**2,x**3,v**2,v**3,x*v,x*x*v,x*v*v]
Pb=np.column_stack(base)
def f(w,k):
    ph=w*t+k*x
    A=np.column_stack([Pb,np.cos(ph),np.sin(ph),x*np.cos(ph),x*np.sin(ph)])
    c,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None)
    return np.mean((A@c-dv_dt)**2)/var
best=(1,0,0)
for w in np.linspace(0.2,1.2,101):
    for k in np.linspace(-1.5,1.5,61):
        r=f(w,k)
        if r<best[0]: best=(r,w,k)
print(best)
